package com.yuegang.zhihui.order.api;import com.yuegang.zhihui.common.core.*;import com.yuegang.zhihui.common.web.*;import com.yuegang.zhihui.order.application.*;import com.yuegang.zhihui.order.security.*;import jakarta.servlet.http.*;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/v1/orders")public final class OrderController{private final OrderService service;private final OrderUserResolver users;public OrderController(OrderService s,OrderUserResolver u){service=s;users=u;}@PostMapping ApiResponse<OrderView>create(@Valid @RequestBody CreateOrderRequest c,HttpServletRequest r){return ok(service.create(users.resolve(r),c),r);}@GetMapping("/{id}")ApiResponse<OrderView>get(@PathVariable String id,HttpServletRequest r){return ok(service.get(users.resolve(r),id),r);}@PostMapping("/{id}/cancel")ApiResponse<OrderView>cancel(@PathVariable String id,@RequestParam long version,HttpServletRequest r){return ok(service.cancel(users.resolve(r),id,version),r);}private static<T>ApiResponse<T>ok(T d,HttpServletRequest r){return ApiResponse.success(d,TraceIdResolver.resolve(r));}}
